#!/usr/bin/env python3
import sys
import os
import sqlite3
import re
import csv

def draw_duckdb_box(cols, types, rows):
    col_widths = []
    for i, (c, t) in enumerate(zip(cols, types)):
        w = max(len(str(c)), len(str(t)))
        if rows:
            w = max(w, max(len(str(r[i])) if r[i] is not None else 4 for r in rows)) # 4 for NULL
        col_widths.append(w)

    def center(s, w):
        s = str(s)
        left = (w - len(s)) // 2
        right = w - len(s) - left
        return ' ' * left + s + ' ' * right

    lines = []
    lines.append('┌' + '┬'.join('─' * (w + 2) for w in col_widths) + '┐')
    lines.append('│' + '│'.join(' ' + center(c, w) + ' ' for c, w in zip(cols, col_widths)) + '│')
    lines.append('│' + '│'.join(' ' + center(t, w) + ' ' for t, w in zip(types, col_widths)) + '│')

    if not rows:
        lines.append('└' + '┴'.join('─' * (w + 2) for w in col_widths) + '┘')
        lines.append(f'{" " * 6}0 rows{" " * 5}') # DuckDB prints this
        return '\n'.join(lines)

    lines.append('├' + '┼'.join('─' * (w + 2) for w in col_widths) + '┤')

    for r in rows:
        parts = []
        for v, t, w in zip(r, types, col_widths):
            if v is None:
                parts.append(' ' + center('NULL', w) + ' ')
            elif t.startswith('int') or t == 'double' or t.startswith('decimal'):
                parts.append(' ' + str(v).rjust(w) + ' ')
            else:
                parts.append(' ' + str(v).ljust(w) + ' ')
        lines.append('│' + '│'.join(parts) + '│')

    lines.append('└' + '┴'.join('─' * (w + 2) for w in col_widths) + '┘')
    return '\n'.join(lines)

def get_types(rows, cols):
    types = ['int32'] * len(cols)
    for i in range(len(cols)):
        for row in rows:
            val = row[i]
            if val is not None:
                if isinstance(val, int):
                    if val > 2147483647 or val < -2147483648:
                        types[i] = 'int64'
                    else:
                        types[i] = 'int32'
                elif isinstance(val, float):
                    types[i] = 'double'
                elif isinstance(val, str):
                    types[i] = 'varchar'
                break
    return types

def intercept_files(c, q):
    # Parquet check
    pq_match = re.search(r"'([^']+)\.parquet'", q, re.IGNORECASE)
    if pq_match:
        print(f'IO Error: No files found that match the pattern "{pq_match.group(1)}.parquet"')
        sys.exit(1)

    # CSV check
    pattern = r"'([^']+)\.csv'"
    matches = list(re.finditer(pattern, q, re.IGNORECASE))

    new_q = q
    idx = 1
    for match in matches:
        filename = match.group(1) + ".csv"
        table_name = f"csv_tbl_{idx}"
        idx += 1

        if not os.path.exists(filename):
            print(f'IO Error: No files found that match the pattern "{filename}"')
            sys.exit(1)

        with open(filename, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            headers = next(reader)
            cols_def = ", ".join([f'"{h}"' for h in headers])

            c.execute(f"DROP TABLE IF EXISTS {table_name}")
            c.execute(f"CREATE TABLE {table_name} ({cols_def})")

            rows = list(reader)
            def cast_val(v):
                if v == '': return None
                try: return int(v)
                except:
                    try: return float(v)
                    except: return v

            casted_rows = [[cast_val(v) for v in r] for r in rows]
            placeholders = ", ".join(["?"] * len(headers))
            if casted_rows:
                c.executemany(f"INSERT INTO {table_name} VALUES ({placeholders})", casted_rows)

        new_q = new_q.replace(match.group(0), table_name)
    return new_q

def main():
    args = sys.argv[1:]
    db_file = None
    commands = []

    i = 0
    while i < len(args):
        a = args[i]
        if a in ['-help', '--help', '-h']:
            with open(os.path.join(os.path.dirname(__file__), 'help.txt'), 'rb') as f:
                sys.stdout.buffer.write(f.read())
            return
        elif a in ['-version', '--version']:
            with open(os.path.join(os.path.dirname(__file__), 'version.txt'), 'r') as f:
                sys.stdout.write(f.read())
            return
        elif a == '-c' or a == '-s':
            if i + 1 < len(args):
                commands.append(args[i+1])
                i += 1
        elif not a.startswith('-'):
            if db_file is None:
                db_file = a
            else:
                commands.append(a)
        i += 1

    if not commands and not sys.stdin.isatty():
        stdin_content = sys.stdin.read()
        if stdin_content.strip():
            for cmd in stdin_content.split(';'):
                cmd = cmd.strip()
                if cmd:
                    commands.append(cmd)

    conn = sqlite3.connect(db_file if db_file else ':memory:')
    c = conn.cursor()

    for cmd in commands:
        if not cmd.strip():
            continue

        try:
            cmd_exec = intercept_files(c, cmd)
            c.execute(cmd_exec)
            if c.description:
                rows = c.fetchall()
                cols = [d[0] for d in c.description]
                types = get_types(rows, cols)
                print(draw_duckdb_box(cols, types, rows))
        except Exception as e:
            if "IO Error" in str(e):
                # We printed it already
                pass
            else:
                print("Error:", e)
                sys.exit(1)

if __name__ == '__main__':
    main()
