        if rows:
            w = max(w, max(len(str(r[i])) if r[i] is not None else 4 for r in rows))
        col_widths.append(w)

    def center(s, w):
        s = str(s)
        left = (w - len(s)) // 2
        right = w - len(s) - left
        return ' ' * left + s + ' ' * right

    lines = []
    lines.append('┌' + '┬'.join('─' * (w + 2) for w in col_widths) + '┐')
    lines.append('│' + '│'.join(' ' + center(c, w) + ' ' for c, w in zip(cols, col_widths)) + '│')
    lines.append('│' + '│'.join(' ' + center(t, w) + ' ' for t, w in zip(types, col_widths)) + '│')

    if not rows:
        lines.append('└' + '┴'.join('─' * (w + 2) for w in col_widths) + '┘')
        lines.append(f"{0} rows".center(len(lines[-1])))
        return '\n'.join(lines)

    lines.append('├' + '┼'.join('─' * (w + 2) for w in col_widths) + '┤')

    for r in rows:
        parts = []
        for v, t, w in zip(r, types, col_widths):
            s = 'NULL' if v is None else str(v)
            if t.startswith('int') or t == 'double' or t.startswith('decimal'):
                parts.append(' ' + s.rjust(w) + ' ')
            else:
                parts.append(' ' + s.ljust(w) + ' ')
        lines.append('│' + '│'.join(parts) + '│')

    lines.append('└' + '┴'.join('─' * (w + 2) for w in col_widths) + '┘')

    if len(rows) >= 10:
        lines.append(f"{len(rows)} rows".center(len(lines[-1])))

    return '\n'.join(lines)

def get_types(rows, cols):
    types = ['int32'] * len(cols)
    for i in range(len(cols)):
        has_float = False
        has_str = False
        has_big_int = False
        for row in rows:
            val = row[i]
            if val is not None:
                if isinstance(val, str):
                    has_str = True
                elif isinstance(val, float):
                    has_float = True
                elif isinstance(val, int) and not isinstance(val, bool):
