        stdin_content = sys.stdin.read()
        if stdin_content.strip():
            for cmd in stdin_content.split(';'):
                cmd = cmd.strip()
                if cmd:
                    commands.append(cmd)

    conn = sqlite3.connect(db_file if db_file else ':memory:')
    c = conn.cursor()

    for cmd in commands:
        if not cmd.strip():
